import os,re,zipfile
from xml.etree import ElementTree as ET
mats=sorted(os.listdir('documents/matters'))[:130]
rx=re.compile(r'(?:tax\s+indemn|indemn(?:ity|ification)\s+(?:for|of)\s+tax)',re.I)
for m in mats:
 for dp,ds,fs in os.walk('documents/matters/'+m):
  for f in fs:
   if f.endswith('.docx'):
    p=os.path.join(dp,f)
    try:
     with zipfile.ZipFile(p) as z:t=' '.join(ET.fromstring(z.read('word/document.xml')).itertext())
     n=len(rx.findall(t))
     if n: print(n+'\t'+p)
    except: pass
